const pauseIngestSite = `-- name: PauseIngestSite :execrows
INSERT INTO ingest.site_pauses (site_id, reason, detail, fetch_attempt_id, run_id)
VALUES (
    $1, $2, $3, $4,
    $5
)
ON CONFLICT (site_id) WHERE resumed_at IS NULL DO NOTHING
`

type PauseIngestSiteParams struct {
	SiteID         string        `db:"site_id" json:"site_id"`
	Reason         string        `db:"reason" json:"reason"`
	Detail         string        `db:"detail" json:"detail"`
	FetchAttemptID sql.NullInt64 `db:"fetch_attempt_id" json:"fetch_attempt_id"`
	RunID          sql.NullInt64 `db:"run_id" json:"run_id"`
}

// Opens a persistent pause. Returns 0 rows affected when the site is already paused; the first
// open pause and its reason are kept.
func (q *Queries) PauseIngestSite(ctx context.Context, arg PauseIngestSiteParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, pauseIngestSite,
		arg.SiteID,
		arg.Reason,
		arg.Detail,
		arg.FetchAttemptID,
		arg.RunID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const releaseIngestHostSlot = `-- name: ReleaseIngestHostSlot :execrows
UPDATE ingest.host_rate_limits SET
    lease_token = NULL,
    lease_expires_at = NULL,
    next_allowed_at = greatest(
        next_allowed_at,
        clock_timestamp() + greatest($1::BIGINT, 5000) * INTERVAL '1 millisecond'
    ),
    updated_at = clock_timestamp()
WHERE host = $2 AND lease_token = $3::UUID
`

type ReleaseIngestHostSlotParams struct {
	IntervalMs int64  `db:"interval_ms" json:"interval_ms"`
	Host       string `db:"host" json:"host"`
	LeaseToken string `db:"lease_token" json:"lease_token"`
}

// Releases a lease and sets the next allowed request time at least interval_ms (never less than
// 5 seconds) from now. Returns 0 rows affected when the lease was lost to expiry.
func (q *Queries) ReleaseIngestHostSlot(ctx context.Context, arg ReleaseIngestHostSlotParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, releaseIngestHostSlot, arg.IntervalMs, arg.Host, arg.LeaseToken)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

