const upsertIngestSourcePage = `-- name: UpsertIngestSourcePage :one
INSERT INTO ingest.source_pages AS p (site_id, url, discovered_via, first_run_id, sitemap_lastmod)
VALUES (
    $1, $2, $3, $4,
    $5
)
ON CONFLICT (url) DO UPDATE SET
    last_seen_at = clock_timestamp(),
    sitemap_lastmod = coalesce(excluded.sitemap_lastmod, p.sitemap_lastmod),
    updated_at = clock_timestamp()
WHERE p.site_id = excluded.site_id
RETURNING p.id, p.state, (p.xmax = 0)::BOOLEAN AS inserted
`

type UpsertIngestSourcePageParams struct {
	SiteID         string        `db:"site_id" json:"site_id"`
	Url            string        `db:"url" json:"url"`
	DiscoveredVia  string        `db:"discovered_via" json:"discovered_via"`
	FirstRunID     sql.NullInt64 `db:"first_run_id" json:"first_run_id"`
	SitemapLastmod sql.NullTime  `db:"sitemap_lastmod" json:"sitemap_lastmod"`
}

type UpsertIngestSourcePageRow struct {
	ID       int64  `db:"id" json:"id"`
	State    string `db:"state" json:"state"`
	Inserted bool   `db:"inserted" json:"inserted"`
}

// Records a page found in a registered sitemap. A known URL keeps its queue state; only sighting
// metadata changes. Returns the page and whether it was newly inserted.
func (q *Queries) UpsertIngestSourcePage(ctx context.Context, arg UpsertIngestSourcePageParams) (UpsertIngestSourcePageRow, error) {
	row := q.db.QueryRowContext(ctx, upsertIngestSourcePage,
		arg.SiteID,
		arg.Url,
		arg.DiscoveredVia,
		arg.FirstRunID,
		arg.SitemapLastmod,
	)
	var i UpsertIngestSourcePageRow
	err := row.Scan(&i.ID, &i.State, &i.Inserted)
	return i, err
}
